#!/usr/bin/env python3
"""Reusable original K-297 transport, with explicit candidate artifact source.

This prepared driver must be invoked explicitly by the campaign owner. It only
launches the pinned canonical dillsp child and retains its original Popen until
lifecycle_core.stop_owned reaps the reserved process group. It never discovers
or adopts an existing PID, and does not run C1/K-288 or P33/K-293 cases.
"""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import runpy
import selectors
import signal
import subprocess
import time

HELPER_SHA = 'e76fe65b6103fc4732aafc4468afc5bbf3d0699a0f79d7f74879165636ebb1a9'
MAX_FRAME = 65536
MAX_CAPTURE = 4 * 1024 * 1024
MAX_MESSAGES = 1024
ABSENT = object()


def digest(path):
    h = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(block)
    return h.hexdigest()


def require(condition, reason):
    if not condition:
        raise RuntimeError(reason)


def sha(value):
    require(isinstance(value, str) and re.fullmatch('[0-9a-f]{64}', value), 'SHA256 pin')
    return value


def read_json(path):
    require(path.is_file() and not path.is_symlink() and path.stat().st_size <= MAX_CAPTURE, 'JSON path/budget')
    return json.loads(path.read_text())


def artifact_check(delivery, report_pin, binary_pins, expected_source):
    require(isinstance(expected_source, str) and re.fullmatch("[0-9a-f]{40}", expected_source), "explicit exact source")
    report = delivery / 'DELIVERY.json'
    require(digest(report) == report_pin, 'delivery report pin')
    value = read_json(report)
    require(value['schema'] == 'zee-local-owned-delivery-1' and value['status'] == 'passed', 'canonical delivery passed')
    require(value['source_sha'] == expected_source and value['signed'] is False and value['published'] is False, 'local source delivery')
    require(value['binary_sha256'] == binary_pins, 'delivery binary pins')
    require(value['build_identity']['source_sha'] == expected_source and value['build_identity']['dirty'] is False, 'clean source BuildJSON')
    seen = set()
    for row in value['files']:
        name = row['path']
        require(isinstance(name, str) and name and not Path(name).is_absolute() and '..' not in Path(name).parts and name not in seen, 'artifact file map')
        seen.add(name)
        path = delivery / name
        require(not path.is_symlink() and path.resolve(strict=True).is_relative_to(delivery) and path.is_file(), 'artifact confinement')
        require(digest(path) == sha(row['sha256']), 'artifact file pin')
    required = {'binaries/' + n for n in ['dil', 'dillsp', 'GIT_SHA', 'SHA256SUMS', 'sbom.spdx.json', 'provenance.intoto.json']}
    require(required <= seen, 'canonical artifact dependencies')
    binaries = delivery / 'binaries'
    require((binaries / 'GIT_SHA').read_text() == expected_source + '\n', 'artifact source pin')
    expected = ''.join(binary_pins[n] + '  ' + n + '\n' for n in ['dil', 'dillsp'])
    require((binaries / 'SHA256SUMS').read_text() == expected, 'canonical checksums')
    require(all(digest(binaries / n) == pin for n, pin in binary_pins.items()), 'binary bytes')
    return value


def span(line, start, end):
    return {'start': {'line': line, 'character': start}, 'end': {'line': line, 'character': end}}


def apply_utf16_edits(text, edits):
    """Independent client oracle: splice UTF-16LE bytes, never server helpers."""
    lines = [line.encode('utf-16-le') for line in text.split('\n')]
    ordered = sorted(edits, key=lambda x: (x['range']['start']['line'], x['range']['start']['character']), reverse=True)
    for edit in ordered:
        start, end = edit['range']['start'], edit['range']['end']
        require(start['line'] == end['line'], 'single-line fixture edit')
        line, a, b = start['line'], start['character'] * 2, end['character'] * 2
        require(0 <= a <= b <= len(lines[line]), 'independent UTF16 edit extent')
        # Strict decoding independently rejects an edit which splits a surrogate.
        lines[line][:a].decode('utf-16-le')
        lines[line][b:].decode('utf-16-le')
        lines[line] = lines[line][:a] + edit['newText'].encode('utf-16-le') + lines[line][b:]
    return '\n'.join(line.decode('utf-16-le') for line in lines)


class OwnedLsp:
    def __init__(self, binary, cwd, helper):
        self.helper = helper
        self.child = None
        self.selector = selectors.DefaultSelector()
        self.raw = {'stdin': bytearray(), 'stdout': bytearray(), 'stderr': bytearray()}
        self.pending = bytearray()
        self.messages = []
        self.events = []
        self.request_id = 0
        self.started = time.monotonic()
        self.deadline = self.started + 120
        self.terminal_status = None
        self.cleanup_status = None
        self.closed_and_reaped = False
        try:
            self.child = subprocess.Popen([str(binary)], cwd=cwd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=helper['controlled_env'](), start_new_session=True, close_fds=True)
            for name in ['stdin', 'stdout', 'stderr']:
                pipe = getattr(self.child, name)
                os.set_blocking(pipe.fileno(), False)
                if name != 'stdin':
                    self.selector.register(pipe, selectors.EVENT_READ, name)
        except BaseException:
            self.close()
            raise

    def check_deadline(self, deadline):
        require(not self.helper['run'].__globals__['CANCELLED'], 'campaign cancelled')
        require(time.monotonic() < min(deadline, self.deadline), 'bounded LSP deadline')

    def parse(self):
        while self.pending:
            boundary = self.pending.find(b'\r\n\r\n')
            if boundary < 0:
                require(len(self.pending) <= 4096, 'response header bound')
                return
            header = bytes(self.pending[:boundary])
            require(boundary <= 4096 and re.fullmatch(rb'Content-Length: [0-9]+', header), 'canonical response framing')
            length = int(header[16:])
            require(0 < length <= MAX_FRAME, 'response body bound')
            end = boundary + 4 + length
            if len(self.pending) < end:
                return
            frame = bytes(self.pending[:end])
            value = json.loads(bytes(self.pending[boundary + 4:end]))
            del self.pending[:end]
            require(isinstance(value, dict) and value.get('jsonrpc') == '2.0', 'response JSON-RPC identity')
            require(len(self.events) < MAX_MESSAGES, 'message bound')
            self.events.append({'direction': 'server', 'seconds': time.monotonic() - self.started, 'frame_sha256': hashlib.sha256(frame).hexdigest(), 'message': value})
            self.messages.append(value)

    def tick(self, deadline, outgoing=None):
        self.check_deadline(deadline)
        for key, _ in self.selector.select(min(0.05, max(0, min(deadline, self.deadline) - time.monotonic()))):
            if key.data == 'stdin':
                try:
                    count = os.write(key.fileobj.fileno(), outgoing)
                except BlockingIOError:
                    continue
                require(count > 0, 'stdin write progress')
                require(len(self.raw['stdin']) + count <= MAX_CAPTURE, 'request capture bound')
                self.raw['stdin'].extend(outgoing[:count])
                del outgoing[:count]
                if not outgoing:
                    self.selector.unregister(key.fileobj)
            else:
                try:
                    block = os.read(key.fileobj.fileno(), 4096)
                except BlockingIOError:
                    continue
                if not block:
                    self.selector.unregister(key.fileobj)
                else:
                    require(len(self.raw[key.data]) + len(block) <= MAX_CAPTURE, 'response capture bound')
                    self.raw[key.data].extend(block)
                    if key.data == 'stdout':
                        self.pending.extend(block)
                        self.parse()

    def send(self, value):
        payload = json.dumps(value, ensure_ascii=False, separators=(',', ':')).encode()
        require(len(payload) <= MAX_FRAME, 'request body bound')
        frame = b'Content-Length: ' + str(len(payload)).encode() + b'\r\n\r\n' + payload
        outgoing = bytearray(frame)
        deadline = min(time.monotonic() + 10, self.deadline)
        self.selector.register(self.child.stdin, selectors.EVENT_WRITE, 'stdin')
        while outgoing:
            self.tick(deadline, outgoing)
        require(len(self.events) < MAX_MESSAGES, 'message bound')
        self.events.append({'direction': 'client', 'seconds': time.monotonic() - self.started, 'frame_sha256': hashlib.sha256(frame).hexdigest(), 'message': value})

    def receive(self, predicate):
        deadline = min(time.monotonic() + 10, self.deadline)
        while True:
            for index, value in enumerate(self.messages):
                if predicate(value):
                    return self.messages.pop(index)
            require(any(key.data in {'stdout', 'stderr'} for key in self.selector.get_map().values()), 'server EOF before response')
            self.tick(deadline)

    def notify(self, method, params=ABSENT):
        value = {'jsonrpc': '2.0', 'method': method}
        if params is not ABSENT:
            value['params'] = params
        self.send(value)

    def request(self, method, params=ABSENT):
        self.request_id += 1
        request_id = self.request_id
        value = {'jsonrpc': '2.0', 'id': request_id, 'method': method}
        if params is not ABSENT:
            value['params'] = params
        self.send(value)
        answer = self.receive(lambda x: x.get('id') == request_id)
        require('error' not in answer and 'result' in answer, 'successful response with explicit result')
        return answer['result']

    def diagnostics(self, uri):
        value = self.receive(lambda x: x.get('method') == 'textDocument/publishDiagnostics' and x.get('params', {}).get('uri') == uri)
        require('id' not in value and isinstance(value['params']['diagnostics'], list), 'diagnostic notification')
        return value['params']['diagnostics']

    def open(self, uri, text):
        self.notify('textDocument/didOpen', {'textDocument': {'uri': uri, 'languageId': 'zee', 'version': 1, 'text': text}})
        return self.diagnostics(uri)

    def close_document(self, uri):
        self.notify('textDocument/didClose', {'textDocument': {'uri': uri}})
        require(self.diagnostics(uri) == [], 'closed document diagnostics clear')

    def position(self, uri, method, line, character):
        params = {'textDocument': {'uri': uri}, 'position': {'line': line, 'character': character}}
        if method == 'rename':
            params['newName'] = 'ad'
        return self.request('textDocument/' + method, params)

    def finish(self):
        require(self.request('shutdown') is None, 'shutdown explicit null')
        self.notify('exit')
        self.child.stdin.close()
        deadline = min(time.monotonic() + 10, self.deadline)
        while self.selector.get_map():
            self.tick(deadline)
        require(not self.pending and not self.messages and not self.raw['stderr'], 'complete frames/no unexpected messages/empty stderr')
        status = self.helper['held_status'](self.child)
        while status is None:
            self.check_deadline(deadline)
            time.sleep(0.01)
            status = self.helper['held_status'](self.child)
        self.terminal_status = status
        require(status == 0, 'normal exit zero before cleanup')

    def close(self):
        try:
            self.selector.close()
        finally:
            if self.child is not None:
                try:
                    self.cleanup_status = self.helper['stop_owned'](self.child)
                    self.closed_and_reaped = True
                finally:
                    for name in ['stdin', 'stdout', 'stderr']:
                        pipe = getattr(self.child, name)
                        if pipe is not None and not pipe.closed:
                            pipe.close()
